<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
$plans=db()->query('SELECT p.*, (SELECT COUNT(*) FROM business_subscriptions s WHERE s.plan_id=p.id) subscriptions FROM membership_plans p ORDER BY p.price_minor')->fetchAll();
$subs=db()->query('SELECT s.*,p.name plan_name,l.name listing_name,u.name owner_name FROM business_subscriptions s JOIN membership_plans p ON p.id=s.plan_id JOIN listings l ON l.id=s.listing_id JOIN users u ON u.id=s.owner_user_id ORDER BY s.created_at DESC LIMIT 100')->fetchAll();
$ledger=db()->query('SELECT t.*,l.name listing_name FROM payment_transactions t LEFT JOIN listings l ON l.id=t.listing_id ORDER BY t.created_at DESC LIMIT 100')->fetchAll();
$adminTitle='Monetization';include __DIR__.'/_header.php';
?>
<div class="owner-callout"><strong>Billing mode: recordkeeping only</strong><p>LocalGuide 5.0 includes plan definitions, subscription records and a transaction ledger. It does not collect money or activate a paid plan based only on a browser request. Razorpay/Stripe checkout, signature validation, refunds, tax handling and webhook processing require credentials and a production integration.</p></div>
<div class="stats-grid"><article class="stat-card"><span>Plan definitions</span><strong><?= count($plans) ?></strong></article><article class="stat-card"><span>Subscription records</span><strong><?= count($subs) ?></strong></article><article class="stat-card"><span>Payment ledger entries</span><strong><?= count($ledger) ?></strong></article><article class="stat-card"><span>Successful recorded payments</span><strong><?= (int)db()->query("SELECT COUNT(*) FROM payment_transactions WHERE status='succeeded'")->fetchColumn() ?></strong><small>Not independently verified against a provider</small></article></div>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">CATALOGUE</span><h2>Membership plans</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Plan</th><th>Price</th><th>Interval</th><th>Subscriptions</th><th>Features</th></tr></thead><tbody><?php foreach($plans as $p): ?><tr><td><strong><?= h($p['name']) ?></strong><small><?= h($p['plan_key']) ?></small></td><td><?= h($p['currency']) ?> <?= number_format(((int)$p['price_minor'])/100,2) ?></td><td><?= h($p['interval_key']) ?></td><td><?= (int)$p['subscriptions'] ?></td><td><?= h(implode(' · ',json_decode((string)$p['features_json'],true)?:[])) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">BILLING RELATIONSHIPS</span><h2>Subscriptions</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Business</th><th>Owner</th><th>Plan</th><th>Status</th><th>Provider</th></tr></thead><tbody><?php foreach($subs as $s): ?><tr><td><?= h($s['listing_name']) ?></td><td><?= h($s['owner_name']) ?></td><td><?= h($s['plan_name']) ?></td><td><?= h($s['status']) ?></td><td><?= h($s['provider']) ?></td></tr><?php endforeach; ?><?php if(!$subs): ?><tr><td colspan="5" class="empty-admin">No subscription records have been created.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">TRANSACTION RECORDS</span><h2>Payment ledger</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Business</th><th>Provider</th><th>Reference</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($ledger as $t): ?><tr><td><?= h($t['created_at']) ?></td><td><?= h($t['listing_name']??'—') ?></td><td><?= h($t['provider']) ?></td><td><?= h($t['provider_reference']?:'—') ?></td><td><?= h($t['currency']) ?> <?= number_format(((int)$t['amount_minor'])/100,2) ?></td><td><?= h($t['status']) ?></td></tr><?php endforeach; ?><?php if(!$ledger): ?><tr><td colspan="6" class="empty-admin">No payment records. This is expected until a payment provider is configured.</td></tr><?php endif; ?></tbody></table></div></div>
